// Captures what GET /api/public-sessions/{slug}/payment-status puts on the wire, by running the real Queue Route Handler and the
// real @rotra/db service (readPublicPaymentStatus, Prisma) against a throwaway local Postgres, on the seed of the public session page:
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55439:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55439/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-paymentstatus.test.mjs
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it.
// Output: apps/api/internal/publicreads/testdata/paymentstatus.golden.json (commit it). The cases are generated by gen-paymentstatus-cases.py.
// Nothing in this read depends on the clock, so no clock is faked. Each case resets what the scenarios change, applies its scenario, then reads.
import { createRequire } from 'node:module'
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, expect, test } from 'vitest'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '../../../..')
const pkgDb = resolve(root, 'packages/db')
const testdata = resolve(here, '../../internal/publicreads/testdata')
const require = createRequire(`${pkgDb}/package.json`)
const { Client } = require('pg')

const adminUrl = process.env.ROTRA_CAPTURE_DB_URL
if (!adminUrl) throw new Error('Set ROTRA_CAPTURE_DB_URL (a local throwaway Postgres).')
const host = new URL(adminUrl).hostname
if (!['127.0.0.1', 'localhost', '::1', '[::1]'].includes(host)) throw new Error(`Refusing non-local host ${host}`)

const cases = JSON.parse(readFileSync(`${testdata}/paymentstatus.cases.json`, 'utf8'))
const dbName = `rotra_capture_${Date.now()}`
const dbUrl = (() => {
  const u = new URL(adminUrl)
  u.pathname = `/${dbName}`
  return u.toString()
})()

let admin
let db
let route

beforeAll(async () => {
  admin = new Client({ connectionString: adminUrl })
  await admin.connect()
  await admin.query(`CREATE DATABASE ${dbName}`)
  db = new Client({ connectionString: dbUrl })
  await db.connect()
  for (const role of ['anon', 'authenticated', 'service_role']) {
    await admin.query(`DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '${role}') THEN CREATE ROLE ${role} NOLOGIN; END IF; END $$`)
  }
  const dir = `${pkgDb}/prisma/migrations`
  for (const name of readdirSync(dir).filter((n) => /^\d/.test(n)).sort()) {
    await db.query(readFileSync(`${dir}/${name}/migration.sql`, 'utf8'))
  }
  await db.query(readFileSync(`${testdata}/publicsession.seed.sql`, 'utf8'))
  process.env.DATABASE_URL = dbUrl
  process.env.ROTRA_DATA_MODE = 'real'
  route = (await import('../../../../apps/queue/src/app/api/public-sessions/[slug]/payment-status/route.ts')).GET
})

afterAll(async () => {
  const { prisma } = await import('../../../../packages/db/src/client/prisma.ts')
  await prisma.$disconnect()
  await db?.end()
  await admin?.query(`DROP DATABASE IF EXISTS ${dbName} WITH (FORCE)`)
  await admin?.end()
})

// What Next does for a dynamic segment: the raw path segment, percent-decoded.
function dispatch(path) {
  const url = new URL(path, 'http://queue.test')
  const slug = decodeURIComponent(url.pathname.split('/')[3])
  return route(new Request(url), { params: Promise.resolve({ slug }) })
}

test('capture', async () => {
  const golden = {}
  for (const c of cases.cases) {
    // one transaction with foreign keys off, like the seed
    await db.query('BEGIN')
    await db.query('SET LOCAL session_replication_role = replica')
    for (const stmt of cases.reset) await db.query(stmt)
    for (const stmt of cases.scenarios[c.scenario]) await db.query(stmt)
    await db.query('COMMIT')
    const res = await dispatch(c.path)
    const bytes = Buffer.from(await res.arrayBuffer())
    const headers = Object.fromEntries([...res.headers.entries()].sort())
    golden[c.name] = { status: res.status, headers, body: JSON.parse(bytes.toString('utf8')) }
  }
  writeFileSync(`${testdata}/paymentstatus.golden.json`, `${JSON.stringify(golden, null, 1)}\n`)
  expect(Object.keys(golden).length).toBe(cases.cases.length)
})
